scripts.许虎对话.txt:
	If ($Event >= 2000) @2000;
	If ($Event == 530) @Label;
	If ($Event == 562) @Label2;
	Say("杨影枫：这位仁兄，请问你为什么一直站在这里？");
	Say("许虎：我喜欢看这里的风景，有什么问题吗？");
	Say("杨影枫：没有，你继续看吧。");
	Return;
	
	
@2000:	
	Say("杨影枫：这位仁兄，请问你为什么一直站在这里？");
	Say("许虎：我喜欢看这里的风景，有什么问题吗？");
	Say("杨影枫：没有，你继续看吧。");
	Return;

@Label:	
	Say("杨影枫：请问<color=Red>落叶谷<color=Black>怎么走？", 2);
	Say("许虎：笔直走，越过<color=Red>天山<color=Black>就到了。年轻人，你是要去拜访<color=Red>武林盟主孟知秋<color=Black>吗？", 0);
	Say("杨影枫：是啊，我要与孟知秋一比高下。", 2);
	Say("许虎：好！有志气，不过江湖上传说孟知秋的武功深不可测，你可要当心啊。", 0);
	Say("杨影枫：多谢好意！", 3);
	Return;
	
@Label2:
	Say("许虎：年轻人，有见到孟知秋吗？", 0);
	Say("杨影枫：见到了，他的武功确实深不可测！", 2);
	Return;
	
@end:
	Return;

