scripts.蔷薇跟随对话.txt:
If ($XiaoHuaSub == 10) @XiaoHuaSub;
If ($XiaoHuaSub == 20) @XiaoHuaSub;
	Return;
@XiaoHuaSub:
	GetRandNum($Temp, 1, 5);
	If ($Temp == 1) @Temp1;
	If ($Temp == 2) @Temp2;
	If ($Temp == 3) @Temp3;
	If ($Temp == 4) @Temp4;
	If ($Temp == 5) @Temp5;
	@Temp1:
		Say("紫衣姑娘：听说这天山上有很多黑熊和恶狼呢，杨公子你害怕吗？", 29);
		Say("杨影枫：姑娘真有趣，我若是害怕就不会上这天山了！", 2);
		Say("紫衣姑娘：可是我害怕呀！所以，你还是应该送我回家。", 29);
		Return;
	@Temp2:
		Say("杨影枫：敢问姑娘尊姓大名？", 2);
		Say("紫衣姑娘：我没有名字。", 29);
		Say("杨影枫：天下怎么会有无名无姓之人？", 2);
		Say("紫衣姑娘：现在除了你我之外，又没有第三个人，你就叫我“姑娘”吧！", 29);
		Say("杨影枫：既然姑娘不愿意说，我也不强求。", 2);
		Return;
	@Temp3:
		Say("杨影枫：姑娘既住在山脚下，应该对天山很熟才对。", 2);
		Say("紫衣姑娘：当然……噢，不熟不熟。我很少离开家。", 29);
		Say("杨影枫：姑娘家里没有兄弟？怎会让你一个女孩儿家上山打猎？", 2);
		Say("紫衣姑娘：我没有兄弟姐妹。", 32);
		Return;
	@Temp4:
		Say("杨影枫：快到姑娘家了吗？", 2);
		Say("紫衣姑娘：快了快了……你这么急干什么……", 31);
		Say("杨影枫：我实在是有正事要办。", 2);
		Say("紫衣姑娘：我这不算正事吗？", 31);
		Return;
	@Temp5:
		Say("紫衣姑娘：你知道吗，我如果不出来打猎，呆在家里很闷的。", 29);
		Say("杨影枫：亲人同侧，其乐融融，岂不是人间美事！", 2);
		Say("紫衣姑娘：外面不是更好吗？拔山涉水，自在逍遥。", 29);
		Return;
	Return;

